  'Working days': 'Jours ouvrés',
  'Calendar days': 'Jours calendaires',
  ' a year': ' par an',
  'The manager or the employee reports an unplanned absence; it counts at once (no hours those days, unavailability sent to Keystone). HR qualifies it on receipt of the supporting document, or directly enters a foreseeable absence. No leave balance is debited; a week fully covered is submitted without hours. At the end of a maternity, an adoption, a parental leave or a long sick leave, the return date is entered on the sheet (career review, art. L6315-1), unless an earlier return is still waiting for its review; that of a long sick leave is not shown to the manager. The effect on CP accrual is given for the record: it is not yet applied to the calculation of the entitlement.': 'Le manager ou le salarié signale une absence imprévue ; elle compte aussitôt (aucune heure ces jours-là, indisponibilité transmise à Keystone). Le service RH la qualifie à réception du justificatif, ou saisit directement une absence prévisible. Aucun solde de congés n’est débité ; une semaine entièrement couverte se soumet sans heure. À la fin d’une maternité, d’une adoption, d’un congé parental ou d’un arrêt longue maladie, la date de reprise est inscrite sur la fiche (entretien de parcours professionnel, art. L6315-1), sauf si une reprise antérieure attend encore son entretien ; celle d’un arrêt longue maladie n’est pas montrée au manager. L’effet sur l’acquisition des CP est indiqué pour mémoire : il n’est pas encore appliqué au calcul des droits.',
