  'Keystone receives the decision and the project manager is notified of it, without the reason.': 'Keystone reçoit la décision et le chef de projet en est notifié, sans le motif.',
  'The refusal is entered in the Cursus log (Settings) with its reason, its date and your name.': 'Le refus est inscrit au journal de Cursus (Paramètres) avec son motif, sa date et votre nom.',
