  'A suspended authorisation carries the reason “Fitness restriction”, without any other detail; the worksites that require it go No Go.': 'Une habilitation suspendue porte le motif « Restriction d’aptitude », sans autre détail ; les chantiers qui l’exigent passent en No Go.',
