  'A substitute has no credit of their own: they receive hours by pooling (art. R2315-6). The counter alerts beyond one and a half times the credit within the month and when the 12-month carry-over is used up, without ever blocking.': 'Un suppléant n’a pas de crédit propre : il reçoit des heures par mutualisation (art. R2315-6). Le compteur alerte au-delà d’une fois et demie le crédit dans le mois et quand le report sur 12 mois est épuisé, sans jamais bloquer.',
