  'No return': 'Aucune reprise',
  'Return date': 'Date de reprise',
  'The return date triggers the proposal of a career path review (art. L6315-1). It is filled in automatically at the end of a maternity, an adoption, a parental leave or a long-term sick leave entered in Leave & absences; to enter here for an absence prior to Cursus. The reason is chosen from the list, without medical information: a long-term sick leave is entered as “long absence”. It stays reserved for HR: the manager only sees the mention “long absence”.': 'La date de reprise déclenche la proposition d’un entretien de parcours professionnel (art. L6315-1). Elle est renseignée automatiquement à la fin d’une maternité, d’une adoption, d’un congé parental ou d’un arrêt longue maladie saisi dans Congés & absences ; à saisir ici pour une absence antérieure à Cursus. Le motif se choisit dans la liste, sans information médicale : un arrêt longue maladie s’inscrit « absence longue ». Il reste réservé au service RH : le manager ne voit que la mention « absence longue ».',
