  'Site number ': 'Matricule de site ',
  'A site number E is given at creation, for good: the person finds it again at each visit.': 'Un matricule de site E est attribué à la création, définitivement : la personne le retrouve à chaque venue.',
  'The sheet is used for titles, authorisations and presences on site; it enters neither payroll, nor leave, nor headcount. The e-mail address allows the person’s Microsoft account to be attached in the other tools.': 'La fiche sert aux titres, aux habilitations et aux présences sur site ; elle n’entre ni dans la paie, ni dans les congés, ni dans les effectifs. L’adresse e-mail permet de rattacher le compte Microsoft de la personne dans les autres outils.',
  'Declaration link': 'Lien de déclaration',
  'I have copied the link': 'J’ai copié le lien',
  'Send this link to the agency: it will not be shown again. If it is lost, revoke it and create another one.': 'Transmettez ce lien à l’agence : il ne sera plus affiché. S’il est perdu, révoquez-le et créez-en un autre.',
  'Send this link to the company: it will not be shown again. If it is lost, revoke it and create another one.': 'Transmettez ce lien à l’entreprise : il ne sera plus affiché. S’il est perdu, révoquez-le et créez-en un autre.',
