  'One link per company or per agency, permanent until it is revoked. Each declaration received awaits the approval of HR; nothing is published or created before.': 'Un lien par entreprise ou par agence, permanent jusqu’à sa révocation. Chaque déclaration reçue attend la validation du service RH ; rien n’est publié ni créé avant.',
