  'A person who has already come keeps their sheet and number: attach them rather than create another one.': 'Une personne déjà venue garde sa fiche et son matricule : rattachez-la plutôt que d’en créer une autre.',
  'A temporary worker is attached to their temporary work sheet (contract, agency, team): create it first in the directory if they have none.': 'Un intérimaire est rattaché à sa fiche d’intérim (contrat, agence, équipe) : créez-la d’abord dans l’annuaire s’il n’en a pas.',
  'Once approved, the visit is published at the gatehouse.': 'Validée, la venue est publiée au poste de garde.',
  // Relevés d’heures des intérimaires (pages/Releves.tsx), Chantiers (pages/Chantiers.tsx).
  'Statement exported — ': 'Relevé exporté — ',
  'Hours statements of the temporary workers': 'Relevés d’heures des intérimaires',
  'Each week, the statement of the approved hours of the temporary workers is e-mailed to their agency (CSV file attached), as soon as all their timesheets of the week are approved, even late (up to five weeks). If a timesheet is missing, the statement can be sent without it: the complete statement follows at its approval. A statement can be sent again at any time.': 'Chaque semaine, le relevé des heures validées des intérimaires part par e-mail à leur agence (fichier CSV joint), dès que toutes leurs feuilles de la semaine sont validées, même avec retard (jusqu’à cinq semaines). S’il manque une feuille, le relevé peut être envoyé sans elle : le relevé complet suit à sa validation. Un relevé se renvoie à tout moment.',
  'No temporary worker on assignment this week.': 'Aucun intérimaire en mission cette semaine.',
