  ' subject to conditions': ' sous réserve',
  'Keystone asks Cursus for each assigned resource. Only the verdict and reason codes leave Cursus: no medical data, no nature of absence, no passport number, no vaccination date.': 'Keystone interroge Cursus pour chaque ressource affectée. Seul le verdict et des codes de motif sortent de Cursus : aucune donnée médicale, aucune nature d’absence, aucun numéro de passeport, aucune date de vaccination.',
