  'Reason codes only': 'Codes de motifs uniquement',
  'Timestamp (“evalue_le”, UTC time): that of the moment of the consultation, as in the answer given to Keystone.': 'Horodatage (« evalue_le », heure UTC) : celui du moment de la consultation, comme dans la réponse faite à Keystone.',
  'Identifier: employee number only. Re-evaluated at each consultation. A change of verdict of a resource (status or reason codes, never a label) is pushed to Keystone after the action that causes it, after an update received from Keystone and every day (expiries) — followed in Settings → Sendings. Level of detail adjustable in the settings.': 'Identifiant : matricule uniquement. Réévalué à chaque consultation. Un changement de verdict d’une ressource (statut ou codes de motif, jamais de libellé) est poussé à Keystone après l’action qui le provoque, après une mise à jour reçue de Keystone et chaque jour (expirations) — suivi dans Paramètres → Envois. Niveau de détail réglable dans les paramètres.',
