  'The first team (in the order of the teams) takes the first group of the cycle, the second the second, and so on. The line team does not change. A takeover can be run again without duplicates: an employee already assigned over the period is left aside.': 'La première équipe (dans l’ordre des équipes) prend le premier groupe du cycle, la deuxième le deuxième, et ainsi de suite. L’équipe hiérarchique ne change pas. Une reprise se rejoue sans doublon : un salarié déjà affecté sur la période est laissé de côté.',
