  'An employee also opens their employee space, and the manager space if they lead a team. Disabling an account closes its sessions at once.': 'Un salarié ouvre aussi son espace collaborateur, et l’espace manager s’il encadre une équipe. Désactiver un compte ferme aussitôt ses sessions.',
