  ': notifications of the approval steps, notices to attend (with their .ics file), hours statements of the temporary work agencies. Each one goes through the sending queue, followed below (Sendings).': ' : notifications des étapes de validation, convocations (avec leur fichier .ics), relevés d’heures des agences d’intérim. Chacun passe par la file d’envoi, suivie ci-dessous (Envois).',
  'Simulation mode (CURSUS_MAIL_FROM not set): no e-mail leaves. Each one is traced in the log and visible in Sendings, marked “simulated”. Set-up by the IT department: docs/EMAILS.md.': 'Mode simulation (CURSUS_MAIL_FROM non définie) : aucun e-mail ne part. Chacun est tracé dans le journal et visible dans Envois, marqué « simulé ». Mise en service par le service informatique : docs/EMAILS.md.',
  'E-mails contain neither health data, nor medical absence reason, nor passport number, nor the comments entered in Cursus: they refer to Cursus for the detail.': 'Les e-mails ne contiennent ni donnée de santé, ni motif d’absence médical, ni numéro de passeport, ni les commentaires saisis dans Cursus : ils renvoient à Cursus pour le détail.',
