  'Recommended order: reference data (Reference data screen), employees, leave balances, certifications, medical visits (fitness, prerequisite of several authorisations), authorisations. Each import can be run again without creating duplicates; after the takeover, Cursus is the reference for the employees and the counters.': 'Ordre conseillé : référentiels (écran Référentiels), salariés, soldes de congés, certifications, visites médicales (l’aptitude, prérequis de plusieurs habilitations), habilitations. Chaque import se rejoue sans créer de doublon ; après la reprise, Cursus fait foi pour les salariés et les compteurs.',
