  ' completed#masc-plural': ' terminés',
  'New module': 'Nouveau module',
  'All modules are archived.': 'Tous les modules sont archivés.',
  'No e-learning module: add those your providers offer (access link, duration, catalogue training course validated).': 'Aucun module d’e-learning : ajoutez ceux que proposent vos organismes (lien d’accès, durée, formation du catalogue validée).',
  'Validated training course': 'Formation validée',
  'Access': 'Accès',
  'No integrated platform: the link opens at the provider. The follow-up is limited to the status, the progress declared or imported, the end date and the success, without connection time. The end of a module, approved by HR, creates the training followed and, for a module attached to the catalogue, the certification. Enrolments and import: Training screen, E-learning tab.': 'Pas de plateforme intégrée : le lien s’ouvre chez l’organisme. Le suivi se limite au statut, à l’avancement déclaré ou importé, à la date de fin et à la réussite, sans temps de connexion. La fin d’un module, validée par le service RH, crée la formation suivie et, pour un module rattaché au catalogue, la certification. Inscriptions et import : écran Formations, onglet E-learning.',
