  'Those providers entered as free text have been taken over as sheets: confirm each one (identity, SIRET, declaration of activity, Qualiopi), or merge it with its duplicate. Two sheets with different SIRETs are never merged.': 'Les organismes saisis en texte libre ont été repris en fiches : confirmez chacune (identité, SIRET, déclaration d’activité, Qualiopi), ou fusionnez-la avec son doublon. Deux fiches aux SIRET différents ne se fusionnent jamais.',
