  'The usual name of a provider is copied onto the catalogue training courses that designate it. A session keeps the provider it had at its creation. Qualiopi missing or expired: a warning, never a block (the OPCO does not fund a non-certified provider).': 'Le nom usuel d’un organisme est recopié sur les formations du catalogue qui le désignent. Une session garde l’organisme qu’elle avait à sa création. Qualiopi absent ou échu : un avertissement, jamais un blocage (l’OPCO ne finance pas un organisme non certifié).',
