  'No rate.': 'Aucun tarif.',
  'Amount excl. VAT': 'Montant HT',
  'Add a rate': 'Ajouter un tarif',
  'The rate in force prefills the cost of a plan line and of an OPCO file, without ever imposing it. Rates and conditions: HR.': 'Le tarif en vigueur préremplit le coût d’une ligne du plan et d’un dossier OPCO, sans jamais l’imposer. Tarifs et conditions : service RH.',
