  'Comparison by training course (cumulative)': 'Comparatif par formation (cumul)',
  'Hot and cold feedback of the trainees, counted with the provider of their session (frozen at its creation) or of their training followed. Under 3 answers, neither average nor rate in the aggregated view; no comment. The evaluations deleted by the retention period are no longer counted.': 'Avis à chaud et à froid des stagiaires, comptés avec l’organisme de leur session (figé à sa création) ou de leur formation suivie. Sous 3 réponses, ni moyenne ni taux dans la vue agrégée ; aucun commentaire. Les évaluations supprimées par la conservation ne sont plus comptées.',
