  // Paramètres (pages/Parametres.tsx et les sections de pages/parametres/).
  'Settings reserved to HR.': 'Paramètres réservés au service RH.',
  'These settings apply to all Cursus users. Each change is saved immediately and traced in the log.': 'Ces réglages s’appliquent à tous les utilisateurs de Cursus. Chaque modification est enregistrée immédiatement et tracée dans le journal.',
  'Read only: the settings and the accounts are reserved to the HR administrator; the transmission to payroll, to the HR administrator and the payroll manager.': 'Consultation : les réglages et les comptes sont réservés à l’administrateur RH ; la transmission à la paie, à l’administrateur RH et au gestionnaire de paie.',
  'Read only: settings, integrations, sends and log of actions, without change. The messages that may touch on health are hidden in the log.': 'Lecture seule : réglages, intégrations, envois et journal des actions, sans modification. Les messages qui peuvent toucher à la santé sont masqués dans le journal.',
