  ' File: failure examined (refusal that the retry will not fix), removed from the current failures, kept in the list.': ' Classer : échec examiné (refus que la relance ne corrigera pas), retiré des échecs en cours, gardé dans la liste.',
  'Sends': 'Envois',
  'Recipient of the sends': 'Destinataire des envois',
  'Status of the sends': 'Statut des envois',
  'Messages sent to Keystone and e-mails sent by Microsoft 365, 100 most recent. A Keystone message keeps its idempotency key from one attempt to the next: Keystone discards a message already received. After a network error, a timeout (10 s) or a 5xx, 408 or 429 error, the send is retried from 1 min to 1 h later, 10 times at most, and the following messages of the same target wait their turn; another error (4xx) puts it at once in failure.': 'Messages envoyés à Keystone et e-mails envoyés par Microsoft 365, 100 plus récents. Un message Keystone garde sa clé d’idempotence d’une tentative à l’autre : Keystone écarte un message déjà reçu. Après une erreur réseau, un délai dépassé (10 s) ou une erreur 5xx, 408 ou 429, l’envoi est retenté de 1 min à 1 h plus tard, 10 fois au plus, et les messages suivants de la même cible attendent leur tour ; une autre erreur (4xx) le met aussitôt en échec.',
