  '): a change requires a reason, kept for HR.': ') : une modification demande un motif, gardé pour le service RH.',
  'Save ': 'Enregistrer ',
  'A public holiday not taken off, like the solidarity day worked, becomes an ordinary day: counted in leave, hours offered, working day of the fixed-days arrangement. ': 'Un férié non chômé, comme la journée de solidarité travaillée, devient un jour ordinaire : décompté dans les congés, heures proposées, jour de travail du forfait. ',
  ' The setting of a year changes neither the previous years nor the counts from before going live.': ' Le réglage d’une année ne change ni les années précédentes ni les décomptes d’avant la mise en service.',
