  ' weeks#count': ' semaines',
  'A timesheet is expected ': 'Une feuille de temps est attendue ',
  ': past this time limit, a timesheet not entered, in draft or to correct is late, flagged in the Working time screen and reminded in one click (e-mail to the employee and their approver). The closing of payroll variables is set in the Payroll section.': ' : passé ce délai, une feuille non saisie, en brouillon ou à corriger est en retard, signalée dans l’écran Temps de travail et relancée en un clic (e-mail au salarié et à son valideur). La clôture des variables de paie se règle dans la section Paie.',
  'Follow-up of timesheets': 'Suivi des feuilles de temps',
  'Timesheet expected on': 'Feuille attendue le',
  'At#time': 'À',
  'Weeks shown': 'Semaines affichées',
  'Month of the signature': 'Mois de la signature',
  'December of the year': 'Décembre de l’année',
  'Enter the reference of the collective agreement that authorises the fixed-days arrangement.': 'Indiquez la référence de l’accord collectif qui autorise le forfait jours.',
  ' to 282.': ' à 282.',
  'Enter a whole percentage, from ': 'Indiquez un pourcentage entier, de ',
  ' to 100.': ' à 100.',
  'Days worked on the approved timesheets of the year (a half-day up to 4 h, a day beyond), compared with the fixed-days of the sheet (': 'Jours travaillés des feuilles validées de l’année (une demi-journée jusqu’à 4 h, une journée au-delà), comparés au forfait de la fiche (',
  ' days at most, art. L3121-64) pro rata of presence. Alert on the timesheet, the approval queue and the sheet; beyond the ceiling, the approval of the timesheet requires a reason. The remaining rest days are recalled on the sheet.': ' jours au plus, art. L3121-64) au prorata de la présence. Alerte sur la feuille, la file de validation et la fiche ; au-delà du plafond, la validation de la feuille exige un motif. Les jours de repos restants sont rappelés sur la fiche.',
  'Values of the law failing an agreement: ': 'Valeurs de la loi à défaut d’accord : ',
  ' days worked at most with an amendment (art. L3121-66), increase of at least ': ' jours travaillés au plus avec avenant (art. L3121-66), majoration d’au moins ',
  ' % (art. L3121-59). The amendment, written and valid for the year, is recorded on the employee’s sheet; its bought-back days go to payroll under the JREN item, deactivated as long as payroll has not given its code: they are then listed “to be entered in Sage” in the batch summary.': ' % (art. L3121-59). L’avenant, écrit et valable pour l’année, s’enregistre sur la fiche du salarié ; ses jours rachetés partent à la paie sous la rubrique JREN, désactivée tant que la paie n’a pas donné son code : ils sont alors listés « à saisir dans Sage » dans le résumé du lot.',
  'Fixed-days arrangement': 'Forfait jours',
  'Alert of the annual cumulative': 'Alerte du cumul annuel',
  'Allow waiving rest days by amendment': 'Permettre la renonciation à des jours de repos par avenant',
  'Only if the collective agreement that authorises the fixed-days arrangement provides for it (art. L3121-63 and L3121-64).': 'Seulement si l’accord collectif qui autorise le forfait jours le prévoit (art. L3121-63 et L3121-64).',
  'Ceiling with amendment (days)': 'Plafond avec avenant (jours)',
  'Minimum increase (%)': 'Majoration minimale (%)',
  'Days bought back in payroll (JREN)': 'Jours rachetés dans la paie (JREN)',
  'Save the waiver': 'Enregistrer la renonciation',
  'Collective agreement on the fixed-days arrangement not referenced: follow-up of the cumulative and alerts only, no waiver amendment.': 'Accord collectif sur le forfait jours non référencé : suivi du cumul et alertes seulement, aucun avenant de renonciation.',
  '“Offer” on the Working time screen adds to the timesheet, for each session of the week the employee is enrolled in (or present, once the session is closed), a line ': '« Proposer » sur l’écran Temps de travail ajoute à la feuille, pour chaque session de la semaine où le salarié est inscrit (ou présent, une fois la session clôturée), une ligne ',
  ' with the planned hours: those of the session schedule, break deducted (': ' avec les heures prévues : celles des horaires de la session, pause déduite (',
  ' per day at most), otherwise the catalogue duration split over its days, one working day at most. Nothing on public holidays, absence or non-working days. The lines already entered are kept: only the line of the same training course and the Keystone tasks already offered are replaced. The hours stay editable by the employee and their approver; internal activity, they never go to Keystone.': ' par jour au plus), sinon la durée du catalogue répartie sur ses jours, une journée de travail au plus. Rien les jours fériés, d’absence ou non travaillés. Les lignes déjà saisies sont gardées : seules la ligne de la même formation et les tâches Keystone déjà proposées sont remplacées. Les heures restent modifiables par le salarié et son valideur ; activité interne, elles ne partent jamais vers Keystone.',
  'Offer the training hours in the timesheets': 'Proposer les heures de formation dans les feuilles de temps',
  'Reminder before the end of Qualiopi validity of a provider': 'Relance avant la fin de validité Qualiopi d’un organisme',
  'First Qualiopi reminder': 'Première relance Qualiopi',
  'Approve automatically the end of an e-learning module on import (“completed” and “passed”), for the modules without a required certificate': 'Valider d’office la fin d’un module d’e-learning à l’import (« terminé » et « réussi »), pour les modules sans attestation exigée',
  'Qualiopi: HR is reminded by the summary of due dates at this step, 15 days before, then once the certification has expired; it is a warning, never a block. E-learning: without automatic end, each end declared or imported awaits HR’s approval, which creates the training followed and, for a module attached to the catalogue, the certification. Evaluations by provider: 3 rolling financial years by default (5 to choose on the sheet).': 'Qualiopi : le service RH est relancé par le récapitulatif des échéances à ce palier, 15 jours avant, puis une fois la certification échue ; c’est un avertissement, jamais un blocage. E-learning : sans fin d’office, chaque fin déclarée ou importée attend la validation du service RH, qui crée la formation suivie et, pour un module rattaché au catalogue, la certification. Évaluations par organisme : 3 exercices glissants par défaut (5 au choix sur la fiche).',
