  'Expense reports activated (entry, approval, check, reimbursement with payroll)': 'Notes de frais activées (saisie, validation, contrôle, remboursement avec la paie)',
  'Deactivated by default: the load test (three and five years of expenses) does not yet meet all its budgets (docs/ARCHITECTURE.md). Activation is your decision: first check the prerequisites below.': 'Désactivées par défaut : l’essai de charge (trois et cinq ans de frais) ne tient pas encore tous ses budgets (docs/ARCHITECTURE.md). L’activation est votre décision : vérifiez d’abord les prérequis ci-dessous.',
  'Prerequisites of the activation': 'Prérequis de l’activation',
  'Approval by the manager, then check': 'Validation du manager, puis contrôle',
  'Approval by the manager alone': 'Validation du manager seule',
  'Submission time limit (months)': 'Délai de soumission (mois)',
  'Supporting document required beyond (€)': 'Justificatif exigé au-delà de (€)',
  'Mileage allowances at the actual horsepower beyond 7 CV (the part beyond the capped scale can be reinstated)': 'Indemnités kilométriques à la puissance réelle au-delà de 7 CV (la part au-delà du barème plafonné est réintégrable)',
  'Ceilings of the internal policy by category (€, empty: none)': 'Plafonds de la politique interne par catégorie (€, vide : aucun)',
  'Save the ceilings': 'Enregistrer les plafonds',
  'An overrun is an alert: the expense is accepted with a reason or brought down to the ceiling at the check. It is never a reinstatement in the contribution base.': 'Un dépassement est une alerte : la dépense est acceptée avec un motif ou ramenée au plafond au contrôle. Ce n’est jamais une réintégration dans l’assiette des cotisations.',
  '2026 amounts of the demonstration taken over from 2025 from memory: to be checked on urssaf.fr. The long-distance travel flat rates stay valued in Sage; Cursus only blocks their combination with actual expenses of the same nature.': 'Montants 2026 de la démonstration repris de 2025 de mémoire : à vérifier sur urssaf.fr. Les forfaits de grand déplacement restent valorisés dans Sage ; Cursus bloque seulement leur cumul avec des frais réels de même nature.',
  'Entries file for accounting: accounts': 'Fichier d’écritures pour la comptabilité : comptes',
  'Account: digits and letters, 13 characters at most; journal: 1 to 6 letters or digits.': 'Compte : chiffres et lettres, 13 caractères au plus ; journal : 1 à 6 lettres ou chiffres.',
  'Save the accounts': 'Enregistrer les comptes',
  'Separator': 'Séparateur',
  'Decimal': 'Décimale',
  'Encoding': 'Encodage',
  'Header line': 'Ligne d’en-tête',
  'Accounts offered (general chart of accounts: 625x, 6061, 6135, VAT 44566, employee 421, journal OD) to be confirmed by accounting. Medical expenses always carry the generic account, with the same label as any expense.': 'Comptes proposés (plan comptable général : 625x, 6061, 6135, TVA 44566, salarié 421, journal OD) à confirmer par la comptabilité. Les frais médicaux portent toujours le compte générique, avec le même libellé que toute dépense.',
  // Paramètres : objectifs et points de suivi, feedback 360° (parametres/ObjectifsSuivis.tsx).
  'The start of the window must precede its end, in the same year.': 'Le début de la fenêtre doit précéder sa fin, dans la même année.',
  'Planned window ': 'Fenêtre prévue ',
  ' (applied if the review becomes mandatory)': ' (appliquée si le point devient obligatoire)',
  'Means of evaluating employees: activated only with the reference of the CSE’s opinion (art. L2312-38) and of the impact assessment (DPIA), once the questionnaire (version ': 'Moyen d’évaluation des salariés : activé seulement avec la référence de l’avis du CSE (art. L2312-38) et de l’analyse d’impact (AIPD), une fois le questionnaire (version ',
  ') has been brought to the employees’ attention (art. L1222-3). Deactivated: no more solicitation; the syntheses already attached stay.': ') porté à la connaissance des salariés (art. L1222-3). Désactivé : plus de sollicitation ; les synthèses déjà jointes restent.',
  'Confidential answers: transferred in one block at the closing, without respondent nor date; returned as an average per group of at least ': 'Réponses confidentielles : versées d’un bloc à la clôture, sans répondant ni date ; restituées en moyenne par groupe d’au moins ',
  ' answers (never fewer than 3), comments after review by HR. Raw answers deleted at the closing of the review, and at the latest ': ' réponses (jamais moins de 3), commentaires après la relecture du service RH. Réponses brutes supprimées à la clôture de l’entretien, et au plus tard ',
  ' months after sending; the synthesis stays in the report.': ' mois après l’envoi ; la synthèse reste au compte rendu.',
  'Objectives and follow-up reviews': 'Objectifs et points de suivi',
  'Follow structured objectives in the annual reviews': 'Suivre des objectifs structurés aux entretiens annuels',
  'Set and evaluated at the annual review, adjusted during the year with a reason; the employee proposes, the manager approves. Deactivated: neither entry nor “My objectives”, the objectives already set stay in the database.': 'Fixés et évalués à l’entretien annuel, ajustés en cours d’année avec un motif ; le salarié propose, le manager valide. Désactivé : ni saisie ni « Mes objectifs », les objectifs déjà fixés restent en base.',
  'Optional objectives (first year)': 'Objectifs facultatifs (première année)',
  'The closing of an annual review does not require the evaluation of the objectives taken over. A proposal of the employee stays to approve or withdraw before the closing.': 'La clôture d’un entretien annuel n’exige pas l’évaluation des objectifs repris. Une proposition du salarié reste à valider ou retirer avant la clôture.',
  'Objectives at most per review': 'Objectifs au plus par entretien',
  'Number of objectives at most per review': 'Nombre d’objectifs au plus par entretien',
  'Make the mid-year review mandatory': 'Rendre le point de mi-année obligatoire',
  'Optional by default. Mandatory: it becomes a due date of each employee concerned by the campaign, reminded like the other reviews.': 'Facultatif par défaut. Obligatoire : il devient une échéance de chaque salarié concerné par la campagne, relancée comme les autres entretiens.',
  'Opening of the window': 'Ouverture de la fenêtre',
  'End of the window (due date)': 'Fin de la fenêtre (échéance)',
  'Save the window': 'Enregistrer la fenêtre',
  'Training wishes expressed in a review': 'Souhaits de formation exprimés en entretien',
  'Transferred automatically at the closing, only with the manager’s favourable opinion.': 'Versés automatiquement à la clôture, seulement avec l’avis favorable du manager.',
  'Each favourable wish becomes a training request to HR, checked like a request from the employee (never twice, nor during an upcoming enrolment); accepted, it gives a plan line of origin “review”. The other wishes stay in the report.': 'Chaque souhait favorable devient une demande de formation au service RH, contrôlée comme une demande du salarié (jamais deux fois, ni pendant une inscription à venir) ; acceptée, elle donne une ligne du plan d’origine « entretien ». Les autres souhaits restent au compte rendu.',
  '360° feedback (opinion of colleagues, the N+2 and supervised employees)': 'Feedback 360° (avis de collègues, du N+2 et de collaborateurs encadrés)',
  'Reference of the CSE’s opinion': 'Référence de l’avis du CSE',
  'E.g.: CSE’s opinion of 12 March 2027': 'Ex. : avis du CSE du 12 mars 2027',
  'Reference of the DPIA': 'Référence de l’AIPD',
  'E.g.: AIPD-2027-02 approved by the DPO': 'Ex. : AIPD-2027-02 validée par le DPO',
  'Save the references': 'Enregistrer les références',
