  '360° feedback deactivated: to activate after the CSE’s opinion, the DPO’s impact assessment and informing the employees.': 'Feedback 360° désactivé : à activer après l’avis du CSE, l’analyse d’impact du DPO et l’information des salariés.',
  // Paramètres : passeport de prévention, pièces justificatives, postes à risques, mise en service (parametres/PasseportPrevention.tsx, Pieces.tsx, PostesRisques.tsx, Reprise.tsx).
  ': columns to adjust when the Caisse des dépôts publishes the employers’ import format.': ' : colonnes à ajuster quand la Caisse des dépôts publiera le format d’import des employeurs.',
  'Export from the Training screen (HR and HSE referent), traced in the log, followed by a mention on each line. Exported are the certifications and training courses followed of the training courses ticked “Prevention passport” in Reference data → Training (': 'Export depuis l’écran Formations (service RH et référent HSE), tracé dans le journal, suivi d’une mention sur chaque ligne. Sont exportées les certifications et formations suivies des formations cochées « Passeport de prévention » dans Référentiels → Formations (',
  ' in force), except those already marked declared. Cursus does not hold the NIR.': ' en vigueur), hors celles déjà marquées déclarées. Cursus ne détient pas le NIR.',
  'Columns of the export, in this order': 'Colonnes de l’export, dans cet ordre',
  'Activated, the dialogs offer to attach a file: absence supporting document (entry, qualification, report by the person concerned), training certificate, signed authorisation title, copy of a document declared by the employee; the employee’s sheet lists the documents and attaches some to the certifications and authorisations already recorded. PDF, JPEG or PNG, recognised on their content, ': 'Activées, les dialogues proposent de joindre un fichier : justificatif d’absence (saisie, qualification, signalement par l’intéressé), attestation de formation, titre d’habilitation signé, copie d’un document déclaré par le collaborateur ; la fiche du collaborateur liste les pièces et en joint aux certifications et habilitations déjà enregistrées. PDF, JPEG ou PNG, reconnus sur leur contenu, ',
  'Activated#fem-plural': 'Activées',
  'Deactivated#fem-plural': 'Désactivées',
  'Storage of the documents': 'Stockage des pièces',
  'To activate after the DPO’s opinion: the absence supporting documents and the copies of documents may contain health data.': 'À activer après l’avis du DPO : les justificatifs d’absence et les copies de documents peuvent contenir des données de santé.',
  'Access: HR sees everything; the HSE / training referent, the certificates and authorisation titles; the employee, their own documents; the manager, the certificates and titles of their team, never an absence supporting document nor a declared document; neither payroll, nor the read-only role. Each upload, consultation and removal is traced in the log, without the file name.': 'Accès : le service RH voit tout ; le référent HSE / formation, les attestations et titres d’habilitation ; le salarié, ses propres pièces ; le manager, les attestations et titres de son équipe, jamais un justificatif d’absence ni un document déclaré ; ni la paie, ni la lecture seule. Chaque envoi, consultation et retrait est tracé dans le journal, sans le nom du fichier.',
  'Storage: “pieces” folder next to the database (data volume), under a random name, encrypted by the server when the IT department has defined the encryption key (mandatory in production; without it, outside production, the files are written in clear), with the SHA-256 fingerprint of each file, checked at each opening and by the integrity check. The backups carry the files that each copy designates, and the restoration puts them back in place. A removed document keeps its description, its file is erased; the retention period follows that of the file it supports. Deactivating the function erases nothing: the documents already attached stay readable.': 'Stockage : dossier « pieces » à côté de la base (volume des données), sous un nom aléatoire, chiffré par le serveur quand le service informatique a défini la clé de chiffrement (obligatoire en production ; sans elle, hors production, les fichiers sont écrits en clair), avec l’empreinte SHA-256 de chaque fichier, vérifiée à chaque ouverture et par le contrôle d’intégrité. Les sauvegardes emportent les fichiers que désigne chaque copie, et la restauration les remet en place. Une pièce retirée garde sa description, son fichier est effacé ; la durée de conservation suit celle du dossier qu’elle justifie. Désactiver la fonction n’efface rien : les pièces déjà jointes restent consultables.',
  'Codex: each document waits in the local folder to be attached, then it is filed in Codex at the hourly pass (category of the personnel file, employee number, end of retention, fingerprint), and its local copy is erased. The documents already in the local folder are taken over the same way. Cursus reads it again for its users, with the same rights, and has it destroyed in Codex when it is removed. Choice refused as long as Codex is not connected by the IT department or its categories are missing from its register.': 'Codex : chaque pièce attend dans le dossier local d’être jointe, puis elle est versée dans Codex au passage horaire (catégorie du dossier du personnel, matricule, fin de conservation, empreinte), et sa copie locale est effacée. Les pièces déjà dans le dossier local sont reprises de la même façon. Cursus la relit pour ses utilisateurs, avec les mêmes droits, et la fait détruire dans Codex à son retrait. Choix refusé tant que Codex n’est pas raccordé par le service informatique ou que ses catégories manquent dans son registre.',
  ' (archived or missing from the catalogue)': ' (archivée ou absente du catalogue)',
  'Required from fixed-term employees, temps and work-study students assigned to a job ticked “List of jobs with particular risks” in Reference data → Jobs (': 'Exigée des salariés en CDD, des intérimaires et des alternants affectés à un poste coché « Liste des postes à risques particuliers » dans Référentiels → Postes (',
  'job ticked': 'poste coché',
  'jobs ticked': 'postes cochés',
  '): only a certification obtained since their entry fulfils it. Without it, the employee is “Non-compliant”, the due date offers to enrol them, and the Go / No Go of the worksites answers No Go (reason “CERTIFICATION”) — reservation if a session is planned before the start. The list of jobs is drawn up after the opinion of the occupational doctor and the CSE (art. L4154-2) and is printed from the Jobs tab.': ') : seule une certification obtenue depuis leur entrée la remplit. Sans elle, le salarié est « Non conforme », l’échéance propose de l’inscrire, et le Go / No Go des chantiers répond No Go (motif « CERTIFICATION ») — réserve si une session est planifiée avant le démarrage. La liste des postes s’établit après avis du médecin du travail et du CSE (art. L4154-2) et s’imprime depuis l’onglet Postes.',
  'Jobs with particular risks': 'Postes à risques particuliers',
  'Enhanced safety training': 'Formation renforcée à la sécurité',
