  'No import': 'Aucun import',
  'After the takeover from Lucca, Cursus is the reference for the list of employees and for the leave counters: entries, departures, employee numbers and balances are kept in Cursus, no longer in Lucca.': 'Après la reprise depuis Lucca, Cursus fait foi pour la liste des salariés et pour les compteurs de congés : entrées, sorties, matricules et soldes se tiennent dans Cursus, plus dans Lucca.',
