  'A whole number from ': 'Un nombre entier de ',
  'A notice of less than 7 days, a reduced daily rest or other durations of night work assume a collective agreement: enter its reference.': 'Un délai de moins de 7 jours, un repos quotidien réduit ou d’autres durées du travail de nuit supposent un accord collectif : indiquez sa référence.',
  'A date (day, month, year).': 'Une date (jour, mois, année).',
  'Module activated: the date of the CSE’s opinion stays required.': 'Module activé : la date de l’avis du CSE reste exigée.',
  ': note it below and save, then activate.': ' : notez-la ci-dessous et enregistrez, puis activez.',
  'Activated after the CSE’s opinion of ': 'Activé après l’avis du CSE du ',
  'Date of the CSE’s opinion': 'Date de l’avis du CSE',
  ' · required to activate': ' · exigée pour activer',
  'Reference of the agreement on the planning': 'Référence de l’accord sur le planning',
  'Values of the law by default: notice period of ': 'Valeurs de la loi par défaut : délai de prévenance de ',
  ' days (art. L3121-47), daily rest of ': ' jours (art. L3121-47), repos quotidien de ',
  ' h (art. L3131-1; an agreement may bring it down to ': ' h (art. L3131-1 ; un accord peut le ramener à ',
  ' h in shift work, never for a minor, with a compensatory rest), night shift of ': ' h en travail posté, jamais pour un mineur, avec un repos compensateur), poste de nuit de ',
  ' h and average of ': ' h et moyenne de ',
  ' h over 12 weeks (art. L3122-6 and L3122-7). Below the notice period, the publication requires the reason of the exceptional circumstances, communicated to the employees.': ' h sur 12 semaines (art. L3122-6 et L3122-7). Sous le délai de prévenance, la publication exige le motif des circonstances exceptionnelles, communiqué aux salariés.',
  'The teams created per shift (2x8, 3x8) for the minimum coverage become the groups of a cycle: each member is assigned to it.': 'Les équipes créées par quart (2x8, 3x8) pour la couverture minimale deviennent les groupes d’un cycle : chaque membre y est affecté.',
  ' Spotted: ': ' Repérées : ',
  ' No team per shift spotted: choose the teams to take over.': ' Aucune équipe par quart repérée : choisissez les équipes à reprendre.',
  'Team planning': 'Planning d’équipe',
  'Activate the team planning': 'Activer le planning d’équipe',
  'Rotation cycles, planning published to the employees, shift swaps. The cycles and the job needs are prepared beforehand (Reference data).': 'Cycles de roulement, planning publié aux salariés, échanges de poste. Les cycles et les besoins de poste se préparent avant (Référentiels).',
  'Module deactivated: the organisation in cycles and the planning tool come under the consultation of the CSE (art. L2312-8). Activate it after its opinion.': 'Module désactivé : l’organisation en cycles et l’outil de planning relèvent de la consultation du CSE (art. L2312-8). Activez-le après son avis.',
  'Company agreement on shift work of …': 'Accord d’entreprise sur le travail posté du …',
  'Save the values': 'Enregistrer les valeurs',
  'Show the employee the planned shifts of their team colleagues': 'Montrer au salarié les postes planifiés de ses collègues d’équipe',
  'Unticked by default: each one only sees their planning and proposes a swap by naming the colleague. Ticked: name and schedule of the published shifts of the team, never an absence nor a rest. Inform the employees before opening it.': 'Décoché par défaut : chacun ne voit que son planning et propose un échange en nommant le collègue. Coché : nom et horaire des postes publiés de l’équipe, jamais une absence ni un repos. Informez les salariés avant de l’ouvrir.',
