  'The #day-of-month': 'Le ',
  ' of the month': ' du mois',
  'Enter the reference of the collective agreement that provides for the replacement rest.': 'Indiquez la référence de l’accord collectif qui prévoit le repos de remplacement.',
  ' The hours included in a weekly flat rate (HSF25, HSF50) stay paid. The mode is frozen on each timesheet at its approval: changing it does not recalculate the weeks already approved.': ' Les heures incluses à un forfait hebdomadaire (HSF25, HSF50) restent payées. Le mode est figé sur chaque feuille à sa validation : le changer ne recalcule pas les semaines déjà validées.',
  'Payroll#section': 'Paie',
  'Overtime': 'Heures supplémentaires',
  'Save the replacement rest': 'Enregistrer le repos de remplacement',
  'Week straddling two months': 'Semaine à cheval sur deux mois',
  'Closing of payroll variables': 'Clôture des variables de paie',
  'Once the closing has passed, the period is closed: a week that belongs to it goes as a back pay on the next period, flagged at the transmission.': 'Une fois la clôture passée, la période est close : une semaine qui lui revient part en rappel sur la période suivante, signalé à la transmission.',
  'Increase of Sunday hours': 'Majoration des heures du dimanche',
  'No legal Sunday increase apart from an agreement or exemption that provides for it. The Sunday hours always go as quantity (HDIM); an increase adds the item MAJ_DIM, frozen on each timesheet at its approval.': 'Aucune majoration légale du dimanche hors accord ou dérogation qui la prévoit. Les heures du dimanche partent toujours en quantité (HDIM) ; une majoration ajoute la rubrique MAJ_DIM, figée sur chaque feuille à sa validation.',
  // Paramètres : récapitulatif des échéances, repos hebdomadaire, confidentialité, Sage Paie (parametres/RelancesEcheances.tsx, ReposHebdomadaire.tsx, Rgpd.tsx, SagePaie.tsx).
