  'HR (the whole scope), each manager (their team, without medical visit nor vaccination) and the HSE referent (training and authorisations) receive the titles, visits, travel formalities, reviews and ends of contract that reach a step: only once per step, from ': 'Le service RH (tout le périmètre), chaque manager (son équipe, sans visite médicale ni vaccination) et le référent HSE (formations et habilitations) reçoivent les titres, visites, formalités de voyage, entretiens et fins de contrat qui atteignent un palier : une seule fois par palier, à partir de ',
  ' h. The timesheets not submitted have their own reminder.': ' h. Les feuilles de temps non soumises ont leur propre relance.',
  'Messaging · summary of due dates': 'Messagerie · récapitulatif des échéances',
  'Send the summary of due dates by e-mail': 'Envoyer le récapitulatif des échéances par e-mail',
