  'Weekly rest': 'Repos hebdomadaire',
  'Saturday and Sunday are greyed out in the timesheets but stay enterable (worksite, trip, imperative). A week of 7 days worked is always flagged (6 days at most and 35 h of consecutive rest, art. L3132-1 and L3132-2); the Sunday hours are too except for an exemption from Sunday rest set for the team (art. L3132-3).': 'Samedi et dimanche sont grisés dans les feuilles de temps mais restent saisissables (chantier, déplacement, impératif). Une semaine de 7 jours travaillés est toujours signalée (6 jours au plus et 35 h de repos consécutives, art. L3132-1 et L3132-2) ; les heures du dimanche le sont sauf dérogation au repos dominical réglée pour l’équipe (art. L3132-3).',
  'Reference of the agreement or the authorisation': 'Référence de l’accord ou de l’autorisation',
