/** Chaînes à paramètres : motif sur la chaîne source entière → remplacement. */
export const FR_REGLES: readonly [RegExp, string][] = [
  [/^(\d+) to handle$/, '$1 à traiter'],
  [/^After (\d+) failed attempts, the account is locked for (\d+) minutes\.$/, 'Après $1 essais infructueux, le compte est bloqué $2 minutes.'],
  [/^at least (\d+) characters$/, '$1 caractères au moins'],
  [/^(\d+) characters at most\.$/, '$1 caractères au plus.'],
  [/^Show (\d+) more$/, 'Afficher $1 de plus'],
  [/^Whole number, at least (\d+)\.$/, 'Nombre entier, au moins $1.'],
  [/^Remove “(.+)” from the file\?$/s, 'Retirer « $1 » du dossier ?'],
  [/^Clock-ins are kept for (\d+) years, then erased\. They are read only by the employee, their manager \(or their deputy for timesheets\) and HR\.$/,
    'Les pointages sont gardés $1 ans, puis effacés. Ils ne sont lus que par le salarié, son manager (ou son suppléant pour les feuilles) et le service RH.'],
  [/^Online, your position is read once, on the click, to check that you are in a clock-in zone: only the result \(in the zone, outside the zone…\) is kept, never the position\. You may refuse: the clock-in is recorded anyway, and is sent at the latest (\d+) seconds after the click\.$/,
    'En ligne, votre position est lue une fois, au clic, pour vérifier que vous êtes sur une zone de pointage : seul le résultat (dans la zone, hors zone…) est gardé, jamais la position. Vous pouvez refuser : le pointage est enregistré quand même, et part au plus tard $1 secondes après le clic.'],
  [/^A request is made within (\d+) days\. Once approved, it adds the missed clock-in or removes the wrong one; the timesheet of an already approved week goes through its reopening first\.$/,
    'Une demande se fait sous $1 jours. Validée, elle ajoute le pointage oublié ou retire le pointage erroné ; la feuille d’une semaine déjà validée passe d’abord par sa réouverture.'],
  [/^Request approved by your manager \(or their deputy\) or by HR, within (\d+) days of the clock-in\.$/,
    'Demande validée par votre manager (ou son suppléant) ou par le service RH, sous $1 jours après le pointage.'],
  [/^(\d+) nights a year, pro rata$/, '$1 nuits par an, au prorata'],
  [/^Their nights count as night work \(threshold of (\d+)\) in the meantime\.$/, 'Leurs nuits comptent au travail de nuit (seuil de $1) en attendant.'],
  [/^No employee exposed in (\d+), nor any night under a schedule to qualify\.$/, 'Aucun salarié exposé en $1, ni de nuit sous un horaire à qualifier.'],
  [/^(\d+) months at most per search\.$/, '$1 mois au plus par recherche.'],
  [/^thresholds pro rata \((\d+) % of the year\)$/, 'seuils au prorata ($1 % de l’année)'],
  [/^A night counts when the shift includes at least 1 h of work between 0:00 and 5:00 \((.+)\), from the shift schedule frozen on the approved timesheet: Cursus only counts the nights from shift schedules, a timesheet without a schedule counts no night\. Nights worked under a schedule qualified “alternating successive shifts” \(Reference data → Schedules\) count towards the threshold of (\d+) nights, the others towards that of (\d+); regulatory thresholds, not adjustable, pro rata for a contract of less than a year; a contract of less than a month is not declared\. Repetitive work, hyperbaric environment, extreme temperatures and noise are ticked on the job \(Reference data → Jobs\) when its holders are exposed to them beyond the threshold after protection\. The export lists the lines to enter in Sage’s DSN with Cursus’s internal codes and the presumed DSN code, to be confirmed by payroll\.$/,
    'Une nuit compte quand le poste comprend au moins 1 h de travail entre 0 h et 5 h ($1), d’après l’horaire de poste figé sur la feuille validée : Cursus ne compte que les nuits issues des horaires de poste, une feuille sans horaire compte sans nuit. Les nuits faites sous un horaire qualifié « équipes successives alternantes » (Référentiels → Horaires) comptent au seuil de $2 nuits, les autres à celui de $3 ; seuils réglementaires, non réglables, au prorata d’un contrat de moins d’un an ; un contrat de moins d’un mois n’est pas déclaré. Travail répétitif, milieu hyperbare, températures extrêmes et bruit se cochent sur le poste (Référentiels → Postes) quand ses titulaires y sont exposés au-delà du seuil après protections. L’export liste les lignes à saisir dans la DSN de Sage avec les codes internes de Cursus et le code DSN présumé, à confirmer par la paie.'],
];

